import fs from 'fs';
import readline from 'readline';

const file = process.argv[2];
const maxLen = 400;

function trunc(s) {
  if (typeof s !== 'string') s = JSON.stringify(s);
  return s.length > maxLen ? s.slice(0, maxLen) + `...[${s.length} chars]` : s;
}

const rl = readline.createInterface({ input: fs.createReadStream(file) });
rl.on('line', (line) => {
  if (!line.trim()) return;
  let obj;
  try { obj = JSON.parse(line); } catch { return; }
  const ts = obj.timestamp || '';
  if (obj.type === 'user' || obj.type === 'assistant') {
    const content = obj.message?.content;
    if (typeof content === 'string') {
      console.log(`[${ts}] ${obj.type}: ${trunc(content)}`);
    } else if (Array.isArray(content)) {
      for (const block of content) {
        if (block.type === 'text') {
          console.log(`[${ts}] ${obj.type} text: ${trunc(block.text)}`);
        } else if (block.type === 'tool_use') {
          console.log(`[${ts}] ${obj.type} tool_use: ${block.name} ${trunc(block.input)}`);
        } else if (block.type === 'tool_result') {
          console.log(`[${ts}] ${obj.type} tool_result: ${trunc(block.content)}`);
        }
      }
    }
  }
});
EOF
